searchBook.JSParser:
@js:
var kw = String(params && params.keyWord ? params.keyWord : '').trim();
var out = [];
try {
  var d = JSON.parse(result);
  var arr = (d && d.novels) ? d.novels : [];
  for (var i = 0; i < arr.length; i++) {
    var n = arr[i] || {};
    var t = String(n.t || '');
    var a = String(n.a || '');
    if (!kw || t.indexOf(kw) > -1 || a.indexOf(kw) > -1) {
      out.push({
        'bookName': t,
        'author': String(a).replace(/^作者/, ''),
        'detailUrl': config.host + '/novel/' + String(n.id || '') + '/',
        'desc': String(n.d || '')
      });
    }
    if (out.length >= 50) break;
  }
} catch (e) {}
return {'list': out};

bookDetail.requestInfo:
@js:
var host = String(config.host || '') || 'https://tuoverse.com';
var u = '';
if (typeof result === 'string' && result) u = result;
if (!u && result && result.url) u = result.url;
if (!u && result && result.detailUrl) u = result.detailUrl;
if (!u && params && params.queryInfo) u = params.queryInfo.url || params.queryInfo.detailUrl || '';
if (!u && params && params.responseUrl) u = params.responseUrl;
u = String(u || '').trim().split(/\s+/)[0] || '';
if (u && u.indexOf('http') !== 0) {
  if (u.indexOf('//') === 0) u = 'https:' + u;
  else if (u.indexOf('/') === 0) u = host + u;
  else u = host + '/' + u;
}
return {'url': u, 'httpHeaders': config.httpHeaders};

